impl Draft {
    fn validate_for_publish(&self) -> Result<(), Vec<Violation>> {
        let mut errs = Vec::new();
        if self.rows.is_empty() { errs.push(Violation::RowsEmpty); }
        if errs.is_empty() { Ok(()) } else { Err(errs) }
    }
}

draft.validate_for_publish()?;      // gate at the use
store.commit(draft)?;               // irreversible step
